"""Planner: proposes a long paper trade, and revises it when the Naysayer objects."""
import json

from src.agents import DATA_NOTE

MODEL = "claude-sonnet-5-5"
MAX_HORIZON = 10    # labels and prices guarantee t+10 exists for every setup

SYSTEM = (
    "You are the Planner on a paper-trading research team. Using the Researcher's facts, "
    "propose one long trade entered at today's close (100). Give a stop below 100, a target "
    "above 100, a holding horizon of 1 to 10 trading days, a one-sentence thesis, and the fact "
    "keys your thesis relies on (only keys from the Researcher's facts). If objections from the "
    "Naysayer are given, revise the plan so it answers each one. " + DATA_NOTE
)

SCHEMA = {
    "type": "object",
    "properties": {
        "stop": {"type": "number"},
        "target": {"type": "number"},
        "horizon_days": {"type": "integer"},
        "thesis": {"type": "string"},
        "facts_cited": {"type": "array", "items": {"type": "string"}},
    },
    "required": ["stop", "target", "horizon_days", "thesis", "facts_cited"],
    "additionalProperties": False,
}


def run(llm, facts, objections, **tags):
    """-> raw plan on the normalized scale (entry = 100)."""
    prompt = json.dumps({"facts": facts, "objections": objections})
    return llm("planner", MODEL, SYSTEM, prompt, SCHEMA, **tags)


def to_plan(raw, ticker, entry):
    """Normalized plan -> trade plan in real prices. Ticker and direction are set by code."""
    scale = entry / 100.0
    return {"ticker": ticker, "direction": "long", "entry": entry,
            "stop": raw["stop"] * scale, "target": raw["target"] * scale,
            "horizon_days": raw["horizon_days"], "thesis": raw["thesis"],
            "facts_cited": list(raw["facts_cited"])}


def validate_plan(plan, facts):
    """None if the plan is valid, else the reason it isn't."""
    if plan["direction"] != "long":
        return "direction must be long"
    if not plan["stop"] < plan["entry"] < plan["target"]:
        return "need stop < entry < target"
    if not isinstance(plan["horizon_days"], int) or not 1 <= plan["horizon_days"] <= MAX_HORIZON:
        return "horizon_days must be an integer from 1 to %d" % MAX_HORIZON
    if not plan["thesis"].strip():
        return "thesis is empty"
    if not plan["facts_cited"]:
        return "facts_cited is empty"
    unknown = [k for k in plan["facts_cited"] if k not in facts]
    if unknown:
        return "facts_cited not in the Researcher's facts: %s" % ", ".join(unknown)
    return None

