"""
from dataclasses import dataclass, field

import numpy as np
import pandas as pd

from src.data import TICKERS, load_prices
from src.features import FEATURE_NAMES
from src.labels import SETUPS_PATH, adjusted_high_low
from src.simulator import first_hit


@dataclass
class Market:
    prices: dict            # ticker -> DataFrame indexed by date: Adj Close, High, Low (High/Low adjusted)
    setups: pd.DataFrame    # data/labels/setups.csv
    arrays: dict = field(init=False)

    def __post_init__(self):
        self.arrays = {t: (df["Adj Close"].to_numpy(float), df["High"].to_numpy(float),
                           df["Low"].to_numpy(float)) for t, df in self.prices.items()}

    def row_index(self, ticker, date):
        return self.prices[ticker].index.get_loc(pd.Timestamp(date))


def prepare_prices(raw):
    """Yahoo prices -> Adj Close plus High/Low on the Adj Close scale."""
    high, low = adjusted_high_low(raw)
    return pd.DataFrame({"Adj Close": raw["Adj Close"], "High": high, "Low": low})


def load_market(setups_path=SETUPS_PATH, tickers=TICKERS):
    prices = {t: prepare_prices(load_prices(t)) for t in tickers}
    return Market(prices, pd.read_csv(setups_path))


def get_prices(market, ticker, end_date, lookback_days=20):
    """The last `lookback_days` rows up to and including end_date. Never anything later."""
    return market.prices[ticker].loc[: pd.Timestamp(end_date)].tail(lookback_days)


def backtest(plan, market, decision_date, features, split="train"):
    """Hit rate of the plan's stop/target/horizon on past train setups.

    Past setups are kept only if each feature the plan cites sits on the same side of its
    train median as today's value, so the backtest tests the plan's thesis, not just its
    levels. A past setup counts only if its outcome window ended before decision_date.
    """
    if split != "train":
        raise ValueError("backtest runs on the train split only")
    stop_ratio = plan["stop"] / plan["entry"]
    target_ratio = plan["target"] / plan["entry"]
    horizon = plan["horizon_days"]
    decision = pd.Timestamp(decision_date)

    train = market.setups[market.setups["split"] == "train"]
    medians = train[FEATURE_NAMES].median()
    conditions = [k for k in plan["facts_cited"] if k in FEATURE_NAMES]
    keep = np.ones(len(train), dtype=bool)
    for k in conditions:
        keep &= (train[k] >= medians[k]).to_numpy() == (features[k] >= medians[k])

    wins = count = 0
    for ticker, date in train.loc[keep, ["ticker", "date"]].itertuples(index=False):
        dates = market.prices[ticker].index
        i = dates.get_loc(pd.Timestamp(date))
        if i + horizon >= len(dates) or dates[i + horizon] >= decision:
            continue  # outcome not fully known on the decision date
        close, high, low = market.arrays[ticker]
        entry = close[i]
        outcome, _ = first_hit(close, high, low, i, entry, entry * stop_ratio,
                               entry * target_ratio, horizon)
        count += 1
        wins += outcome == "win"
    return {"hit_rate": wins / count if count else None, "count": count,
            "wins": wins, "conditions": conditions}

