    if math["ev_per_share"] is None or math["ev_per_share"] <= 0:
        # Hard rule from the spec, enforced in code so no LLM call is spent on it.
        return "block", ["expected value is not positive (p=%s from %d backtest cases, reward/risk %.2f)"
                         % (math["p"], math["backtest_count"], math["reward_risk"])]
    view = {k: math[k] for k in ("p", "backtest_count", "conditions", "ev_pct", "reward_risk")}
    prompt = json.dumps({"plan": plan_view, "facts": facts, "math": view})
    out = llm("naysayer", SYSTEM, prompt, SCHEMA, **tags)
    err = validate_verdict(out)
    if err:
        return "block", ["invalid naysayer output: " + err]
    return out["verdict"], list(out["objections"])

